import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { PermissionDenied, SchemaInvalid } from './errors.mjs';
import { PHASES } from './project.mjs';
import { ROOT } from './workspace.mjs';

// Agent roles are defined once in agents/<role>.md (frontmatter plus instructions). This module
// reads them, generates the Claude Code subagents and Cursor rules from them, checks that the
// generated files still match, and routes each phase to the agents that work in it.

export const AGENTS_DIR = join(ROOT, 'agents');

// The task contract's agent enum is the list of roles.
const TASK_SCHEMA = JSON.parse(readFileSync(join(ROOT, 'schemas', 'task.schema.json'), 'utf8'));
export const AGENT_IDS = TASK_SCHEMA.properties.agent.enum;

const PHASE_NAMES = new Set(PHASES.map((p) => p.name));
const KNOWN_TOOLS = new Set(['Read', 'Write', 'Edit', 'Glob', 'Grep', 'Bash', 'WebSearch', 'WebFetch']);
const FIELDS = { id: 'string', name: 'string', description: 'string', phases: 'list', writes: 'list', tools: 'list' };

// Frontmatter is a flat block of `key: value` lines; lists are written inline as [a, b].
export function parseAgent(text, file = 'agent') {
  const m = text.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!m) throw new SchemaInvalid(`${file} has no frontmatter block`);
  const meta = {};
  for (const line of m[1].split('\n')) {
    if (!line.trim()) continue;
    const i = line.indexOf(':');
    if (i <= 0) throw new SchemaInvalid(`${file}: cannot read frontmatter line "${line}"`);
    const key = line.slice(0, i).trim();
    const raw = line.slice(i + 1).trim();
    if (!(key in FIELDS)) throw new SchemaInvalid(`${file}: unknown field "${key}"`);
    if (FIELDS[key] === 'list') {
      if (!/^\[.*\]$/.test(raw)) throw new SchemaInvalid(`${file}: ${key} must be a list like [a, b]`);
      meta[key] = raw.slice(1, -1).split(',').map((s) => s.trim()).filter(Boolean);
    } else {
      meta[key] = raw;
    }
  }
  for (const key of Object.keys(FIELDS)) {
    if (!(key in meta)) throw new SchemaInvalid(`${file}: missing field "${key}"`);
  }
  return { ...meta, body: m[2].trim() + '\n' };
}

function validate(agent, file) {
  const errors = [];
  if (!AGENT_IDS.includes(agent.id)) errors.push(`id "${agent.id}" is not one of ${AGENT_IDS.join(', ')}`);
  if (!file.endsWith(`${agent.id}.md`)) errors.push(`file name must be ${agent.id}.md`);
  for (const p of agent.phases) if (!PHASE_NAMES.has(p)) errors.push(`unknown phase ${p}`);
  if (!agent.phases.length) errors.push('phases is empty');
  for (const t of agent.tools) if (!KNOWN_TOOLS.has(t)) errors.push(`unknown tool ${t}`);
  for (const w of agent.writes) if (/^\/|^[A-Za-z]:|\.\./.test(w)) errors.push(`writes path ${w} must be project-relative`);
  if (errors.length) throw new SchemaInvalid(`${file} is not a valid agent definition`, { details: errors });
}

export function loadAgents(dir = AGENTS_DIR) {
  const files = readdirSync(dir).filter((f) => f.endsWith('.md')).sort();
  const agents = files.map((f) => {
    const agent = parseAgent(readFileSync(join(dir, f), 'utf8'), f);
    validate(agent, f);
    return agent;
  });
  const missing = AGENT_IDS.filter((id) => !agents.some((a) => a.id === id));
  if (missing.length) throw new SchemaInvalid(`Agent definitions are missing for ${missing.join(', ')}`, { hint: `Add agents/<role>.md for each.` });
  return agents;
}

const banner = (agent) => `<!-- Generated by forge agents generate from agents/${agent.id}.md. Edit that file, not this one. -->`;

// Claude Code subagent: .claude/agents/<id>.md
export function renderClaudeCode(agent) {
  return [
    '---',
    `name: ${agent.id}`,
    `description: ${JSON.stringify(agent.description)}`,
    `tools: ${agent.tools.join(', ')}`,
    '---',
    '',
    banner(agent),
    '',
    agent.body.trimEnd(),
    '',
    writesNote(agent),
    '',
  ].join('\n');
}

// Cursor project rule: .cursor/rules/<id>.mdc. Cursor runs no subagents or hooks, so the rule
// is attached by the files the role writes, or picked by its description.
export function renderCursor(agent) {
  return [
    '---',
    `description: ${JSON.stringify(`${agent.name}: ${agent.description}`)}`,
    `globs: ${agent.writes.map((w) => `workspace/*/${w}`).join(',')}`,
    'alwaysApply: false',
    '---',
    '',
    banner(agent),
    '',
    agent.body.trimEnd(),
    '',
    writesNote(agent),
    '',
  ].join('\n');
}

function writesNote(agent) {
  const where = agent.writes.length
    ? `You write only to these project paths: ${agent.writes.map((w) => `\`${w}\``).join(', ')}.`
    : "You write only to the files your task contract's `owns_files` lists.";
  return `## Boundaries\n\n${where} The forge CLI owns the project state, the ledger and approvals; change them only through forge commands.`;
}

// Every generated file, keyed by its path relative to the harness root.
export function generatedFiles(agents) {
  const out = {};
  for (const a of agents) {
    out[`.claude/agents/${a.id}.md`] = renderClaudeCode(a);
    out[`.cursor/rules/${a.id}.mdc`] = renderCursor(a);
  }
  return out;
}

export function writeGenerated(agents, root = ROOT) {
  const files = generatedFiles(agents);
  for (const [rel, content] of Object.entries(files)) {
    const file = join(root, rel);
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
  }
  // Remove generated files whose source was deleted.
  for (const dir of ['.claude/agents', '.cursor/rules']) {
    const full = join(root, dir);
    if (!existsSync(full)) continue;
    for (const f of readdirSync(full)) {
      const rel = `${dir}/${f}`;
      if (!(rel in files) && readFileSync(join(full, f), 'utf8').includes('Generated by forge agents generate')) rmSync(join(full, f));
    }
  }
  return Object.keys(files);
}

// Lists generated files that are missing or differ from what the sources produce.
export function checkGenerated(agents, root = ROOT) {
  const drift = [];
  for (const [rel, content] of Object.entries(generatedFiles(agents))) {
    const file = join(root, rel);
    if (!existsSync(file)) drift.push({ file: rel, problem: 'missing' });
    else if (readFileSync(file, 'utf8').replace(/\r\n/g, '\n') !== content) drift.push({ file: rel, problem: 'differs from its source' });
  }
  return drift;
}

// The agents that work in a phase, in the order they are defined.
export function agentsForPhase(phase, agents = loadAgents()) {
  if (!PHASE_NAMES.has(phase)) throw new SchemaInvalid(`Unknown phase ${phase}`);
  return agents.filter((a) => a.phases.includes(phase)).map((a) => a.id);
}

// Refuses a task whose agent does not work in the current phase.
export function assertAgentForPhase(phase, agentId, agents = loadAgents()) {
  const allowed = agentsForPhase(phase, agents);
  if (!allowed.includes(agentId)) {
    throw new PermissionDenied(`The ${agentId} agent does not work in phase ${phase}`, {
      hint: allowed.length ? `Agents for ${phase}: ${allowed.join(', ')}.` : `No agent works in ${phase}; the CLI handles it.`,
      details: { phase, agent: agentId, allowed },
    });
  }
  return true;
}
